        public async Task<IResult> HandleLeaveSave(Dictionary<string, JsonElement> values, string userId)
        {
            var id = int.Parse(values.GetValueOrDefault("id")?.ToString() ?? "0");
            var fromDate = DateTime.Parse(values.GetValueOrDefault("from_date")?.ToString() ?? "2000-01-01");
            var toDate = DateTime.Parse(values.GetValueOrDefault("to_date")?.ToString() ?? "2000-01-01");
            var isFromHd = int.Parse(values.GetValueOrDefault("is_from_hd")?.ToString() ?? "0");
            var isToHd = int.Parse(values.GetValueOrDefault("is_to_hd")?.ToString() ?? "0");
            var remarks = values.GetValueOrDefault("remarks")?.ToString() ?? "";
            var phoneC = values.GetValueOrDefault("phone_c")?.ToString() ?? "";
            var leaveTypeId = int.Parse(values.GetValueOrDefault("leave_type_id")?.ToString() ?? "1");
            var leaveCancel = int.Parse(values.GetValueOrDefault("leave_cancel")?.ToString() ?? "0");
            var leaveCancelReq = int.Parse(values.GetValueOrDefault("leave_cancel_request")?.ToString() ?? "0");

            if (id != 0)
            {
                var leaveObj = new Leaves(id);
                if (leaveCancel != 0)
                {
                    if (string.IsNullOrWhiteSpace(remarks))
                    {
                        return Results.BadRequest(new { message = "Please enter remarks for cancellation." });
                    }
                    leaveObj.LeaveStatusTypeId = 4;
                    if (leaveObj.HasChanged())
                    {
                        await leaveObj.SaveAsync();
                        await LeaveStatusHistory.AddAsync(id, leaveObj.LeaveStatusTypeId, userId, remarks);
                        await SendCancellationEmails(userId, leaveObj);
                    }
                    return Results.Ok(new { message = "Leave cancelled." });
                }
                if (leaveCancelReq != 0)
                {
                    leaveObj.LeaveStatusTypeId = 5;
                    if (leaveObj.HasChanged())
                    {
                        await leaveObj.SaveAsync();
                        await LeaveStatusHistory.AddAsync(id, leaveObj.LeaveStatusTypeId, userId, "Leave Cancellation Requested");
                        await SendCancellationRequestEmails(userId, leaveObj);
                    }
                    return Results.Ok(new { message = "Leave cancellation requested." });
                }
            }
            else
            {
                var leaveObj = new Leave
                {
                    FromDate = fromDate,
                    ToDate = toDate,
                    IsFromHd = isFromHd == 1 ? "Y" : "N",
                    IsToHd = isToHd == 1 ? "Y" : "N",
                    Remarks = remarks,
                    PhoneC = phoneC,
                    LeaveTypeId = leaveTypeId,
                    LeaveStatusTypeId = 1,
                    CreatedBy = userId,
                    CreatedTs = DateTime.UtcNow
                };

                if (fromDate == DateTime.Parse("2000-01-01") || !IsValidDate(fromDate))
                {
                    return Results.BadRequest(new { message = "Please enter from date." });
                }
                if (toDate == DateTime.Parse("2000-01-01") || !IsValidDate(toDate))
                {
                    return Results.BadRequest(new { message = "Please enter to date." });
                }
                if (toDate < fromDate)
                {
                    return Results.BadRequest(new { message = "Please enter valid date range." });
                }

                var exists = await Leaves.CheckLeaveExistsAsync(leaveObj);
                if (exists != 0)
                {
                    return Results.BadRequest(new { message = "Date overlapping. Please select different date range." });
                }

                var isApproved = await Leaves.CheckApprovedTsAsync(leaveObj);
                if (isApproved)
                {
                    return Results.BadRequest(new { message = "The timesheet has been already approved for this week. Please get your timesheet rejected first before applying for leave." });
                }

                var leaveId = await Leaves.ApplyAsync(leaveObj);
                if (leaveId != 0)
                {
                    await LeaveStatusHistory.AddAsync(leaveId, 1, userId, remarks);
                    await SendLeaveApplicationEmails(userId, leaveObj);
                    return Results.Ok(new { message = "Leave has been successfully applied." });
                }
            }

            return Results.BadRequest(new { message = "An error occurred." });
        }

